<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Maze Game - Bot Discovery</title>
    <style>
        body {
            margin: 0;
            padding: 20px;
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            background-color: #1a1a1a;
            color: #fff;
        }
        h1 { margin: 0 0 20px 0; }
        #maze { border: 2px solid #fff; margin-bottom: 20px; display: block; }
        .controls {
            display: flex;
            gap: 20px;
            align-items: center;
            margin-bottom: 20px;
        }
        button {
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
        }
        button:hover { background-color: #45a049; }
        .stats { display: flex; gap: 30px; font-size: 18px; }
        #timer, #completed { font-weight: bold; color: #4CAF50; }
    </style>
</head>
<body>
    <h1>Maze Game - Bot Discovery</h1>
    <div class="controls">
        <button id="reset">Reset</button>
        <div class="stats">
            <div>Timer: <span id="timer">0</span> ticks</div>
            <div>Completed: <span id="completed">0</span>/24</div>
        </div>
    </div>
    <canvas id="maze"></canvas>

    <script>
        class SeededRandom {
            constructor(seed = 1) {
                this.seed = seed >>> 0;
            }
            next() {
                this.seed = (this.seed * 1664525 + 1013904223) >>> 0;
                return (this.seed >>> 0) / 4294967296;
            }
            nextInt(max) {
                return Math.floor(this.next() * max);
            }
        }

        class Maze {
            constructor(rows, cols, seed) {
                this.rows = rows;
                this.cols = cols;
                this.rng = new SeededRandom(seed);
                this.cells = Array(rows).fill(null).map(() =>
                    Array(cols).fill(null).map(() => ({
                        n: true, e: true, s: true, w: true
                    }))
                );
                this.generate();
            }
            generate() {
                const visited = Array(this.rows).fill(null).map(() => Array(this.cols).fill(false));
                this.carve(0, 0, visited);
            }
            carve(r, c, visited) {
                visited[r][c] = true;
                const directions = [
                    {dr: -1, dc: 0, from: 'n', to: 's'},
                    {dr: 1, dc: 0, from: 's', to: 'n'},
                    {dr: 0, dc: -1, from: 'w', to: 'e'},
                    {dr: 0, dc: 1, from: 'e', to: 'w'}
                ];
                for (let i = 3; i > 0; i--) {
                    const j = this.rng.nextInt(i + 1);
                    [directions[i], directions[j]] = [directions[j], directions[i]];
                }
                for (const {dr, dc, from, to} of directions) {
                    const nr = r + dr, nc = c + dc;
                    if (nr >= 0 && nr < this.rows && nc >= 0 && nc < this.cols && !visited[nr][nc]) {
                        this.cells[r][c][from] = false;
                        this.cells[nr][nc][to] = false;
                        this.carve(nr, nc, visited);
                    }
                }
            }
        }

        class Bot {
            constructor(id, r, c, seed) {
                this.id = id;
                this.r = r;
                this.c = c;
                this.path = [{r, c}];
                this.deadEnds = [];
                this.finishTick = null;
                this.passageUses = new Map();
                this.rng = new SeededRandom(seed + id * 12345);
                this.directions = ['n', 'e', 's', 'w'];
                for (let i = 3; i > 0; i--) {
                    const j = this.rng.nextInt(i + 1);
                    [this.directions[i], this.directions[j]] = [this.directions[j], this.directions[i]];
                }
            }
            canMove(maze, dir) {
                if (maze.cells[this.r][this.c][dir]) return false;
                const key = this.getPassageKey(dir);
                return (this.passageUses.get(key) || 0) < 2;
            }
            getNeighbor(dir) {
                const d = {n: [-1, 0], s: [1, 0], e: [0, 1], w: [0, -1]};
                const [dr, dc] = d[dir];
                return [this.r + dr, this.c + dc];
            }
            getPassageKey(dir) {
                const [nr, nc] = this.getNeighbor(dir);
                const r1 = Math.min(this.r, nr), c1 = Math.min(this.c, nc);
                const r2 = Math.max(this.r, nr), c2 = Math.max(this.c, nc);
                return `${r1},${c1},${r2},${c2}`;
            }
            move(maze) {
                for (const dir of this.directions) {
                    if (!this.canMove(maze, dir)) continue;
                    const [nr, nc] = this.getNeighbor(dir);
                    if (this.path.some(p => p.r === nr && p.c === nc)) continue;
                    if (this.deadEnds.some(d => d.r === nr && d.c === nc)) continue;
                    this.r = nr;
                    this.c = nc;
                    this.path.push({r: nr, c: nc});
                    const key = this.getPassageKey(dir);
                    this.passageUses.set(key, (this.passageUses.get(key) || 0) + 1);
                    return true;
                }
                if (this.path.length > 1) {
                    if (!this.deadEnds.some(d => d.r === this.r && d.c === this.c)) {
                        this.deadEnds.push({r: this.r, c: this.c});
                    }
                    const prev = this.path[this.path.length - 2];
                    const dirs = {n: [-1, 0], s: [1, 0], e: [0, 1], w: [0, -1]};
                    let backDir = null;
                    for (const [d, [dr, dc]] of Object.entries(dirs)) {
                        if (this.r + dr === prev.r && this.c + dc === prev.c) {
                            backDir = d;
                            break;
                        }
                    }
                    if (backDir) {
                        const key = this.getPassageKey(backDir);
                        this.passageUses.set(key, (this.passageUses.get(key) || 0) + 1);
                    }
                    this.r = prev.r;
                    this.c = prev.c;
                    this.path.push({r: prev.r, c: prev.c});
                    return true;
                }
                return false;
            }
        }

        class Game {
            constructor() {
                this.size = {rows: 21, cols: 21};
                this.canvas = document.getElementById('maze');
                this.ctx = this.canvas.getContext('2d');
                this.canvas.width = 630;
                this.canvas.height = 630;
                this.cellSize = this.canvas.width / this.size.cols;
                this.spawn = {r: 0, c: 0};
                this.exit = {r: 20, c: 20};
                this.maze = null;
                this.bots = [];
                this.elapsed = 0;
                this.gameActive = true;
                this.reset();
                document.getElementById('reset').addEventListener('click', () => this.reset());
            }
            reset(seed) {
                this.seed = seed !== undefined ? seed : Math.random() * 1e9 | 0;
                this.maze = new Maze(this.size.rows, this.size.cols, this.seed);
                this.bots = [];
                for (let i = 0; i < 24; i++) {
                    this.bots.push(new Bot(i, this.spawn.r, this.spawn.c, this.seed));
                }
                this.elapsed = 0;
                this.gameActive = true;
                this.render();
                this.updateUI();
            }
            tick(n) {
                if (!this.gameActive) return;
                for (let i = 0; i < n; i++) {
                    let activeBots = 0;
                    for (const bot of this.bots) {
                        if (bot.finishTick === null) {
                            bot.move(this.maze);
                            if (bot.r === this.exit.r && bot.c === this.exit.c) {
                                bot.finishTick = this.elapsed;
                            } else {
                                activeBots++;
                            }
                        }
                    }
                    if (activeBots > 0) {
                        this.elapsed++;
                    } else {
                        this.gameActive = false;
                        break;
                    }
                }
                this.render();
                this.updateUI();
            }
            walls(r, c) {
                const cell = this.maze.cells[r][c];
                return {n: cell.n, e: cell.e, s: cell.s, w: cell.w};
            }
            render() {
                this.ctx.fillStyle = '#1a1a1a';
                this.ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);
                this.ctx.strokeStyle = '#ffffff';
                this.ctx.lineWidth = 2;
                for (let r = 0; r < this.size.rows; r++) {
                    for (let c = 0; c < this.size.cols; c++) {
                        const cell = this.maze.cells[r][c];
                        const x = c * this.cellSize;
                        const y = r * this.cellSize;
                        if (cell.n) {
                            this.ctx.beginPath();
                            this.ctx.moveTo(x, y);
                            this.ctx.lineTo(x + this.cellSize, y);
                            this.ctx.stroke();
                        }
                        if (cell.s) {
                            this.ctx.beginPath();
                            this.ctx.moveTo(x, y + this.cellSize);
                            this.ctx.lineTo(x + this.cellSize, y + this.cellSize);
                            this.ctx.stroke();
                        }
                        if (cell.w) {
                            this.ctx.beginPath();
                            this.ctx.moveTo(x, y);
                            this.ctx.lineTo(x, y + this.cellSize);
                            this.ctx.stroke();
                        }
                        if (cell.e) {
                            this.ctx.beginPath();
                            this.ctx.moveTo(x + this.cellSize, y);
                            this.ctx.lineTo(x + this.cellSize, y + this.cellSize);
                            this.ctx.stroke();
                        }
                    }
                }
                const colors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2', '#F8B88B', '#A9DFBF', '#F5B7B1', '#D7BDE2', '#A3E4D7', '#F9E79F', '#D5A6BD', '#85C1E2', '#F8B88B', '#ABEBC6', '#F9E79F', '#F5B7B1', '#D2B4DE', '#A9CCE3', '#FADBD8', '#ABEBC6'];
                for (let i = 0; i < this.bots.length; i++) {
                    const bot = this.bots[i];
                    const x = (bot.c + 0.5) * this.cellSize;
                    const y = (bot.r + 0.5) * this.cellSize;
                    this.ctx.fillStyle = colors[i];
                    this.ctx.beginPath();
                    this.ctx.arc(x, y, this.cellSize * 0.25, 0, Math.PI * 2);
                    this.ctx.fill();
                }
                this.ctx.fillStyle = '#00FF00';
                const ex = (this.exit.c + 0.5) * this.cellSize;
                const ey = (this.exit.r + 0.5) * this.cellSize;
                this.ctx.fillRect(ex - 5, ey - 5, 10, 10);
            }
            updateUI() {
                const completed = this.bots.filter(b => b.finishTick !== null).length;
                document.getElementById('timer').textContent = this.elapsed;
                document.getElementById('completed').textContent = completed;
            }
        }

        const game = new Game();
        window.game = {
            tick: (n) => game.tick(n),
            reset: (seed) => game.reset(seed),
            get elapsed() { return game.elapsed; },
            get size() { return game.size; },
            get spawn() { return game.spawn; },
            get exit() { return game.exit; },
            walls: (r, c) => game.walls(r, c),
            get bots() { return game.bots; }
        };
    </script>
</body>
</html>
